import Foundation
import UniformTypeIdentifiers

// The same list CaptionImporter.contentTypes builds.
var types: [UTType] = [.plainText, .text]
if let srt = UTType(filenameExtension: "srt") { types.insert(srt, at: 0) }
print("offered:", types.map { $0.identifier })

for ext in ["vtt", "srt", "txt"] {
    guard let t = UTType(filenameExtension: ext) else { print(ext, "no type"); continue }
    print(ext, "->", t.identifier, "dynamic:", t.isDynamic,
          "supertypes:", t.supertypes.map { $0.identifier }.sorted())
    print("   conforms to an offered type:", types.contains { t.conforms(to: $0) })
}

// What a real file on disk reports.
let dir = URL(fileURLWithPath: CommandLine.arguments[1])
let url = dir.appendingPathComponent("d46_sample.vtt")
try "WEBVTT\n\n00:00:01.000 --> 00:00:02.000\nHello\n".write(to: url, atomically: true, encoding: .utf8)
let values = try url.resourceValues(forKeys: [.contentTypeKey])
if let t = values.contentType {
    print("file on disk:", t.identifier, "conforms:", types.contains { t.conforms(to: $0) })
}

